"""Lesson 12 student pages with actual source-linked control-flow excerpts."""
STYLE+='''body{overflow-wrap:anywhere}.control-grid{display:grid;grid-template-columns:2fr 1fr;gap:18px;align-items:end}select{width:100%;font:700 20px/1.5 "Segoe UI",Arial;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--paper);color:var(--ink)}.workspace{margin:24px 0}.json-view{max-height:520px}.markdown-body{white-space:normal!important}.markdown-body li{margin:12px 0}.stats{grid-template-columns:1fr}.table{max-width:100%}#notice:empty{display:none}#controls-observed,#lifecycle{font-size:21px;max-height:450px;overflow:auto}#controls-observed li,#lifecycle li{margin:12px 0}.file-view{font-size:23px}.workflow-step{scroll-margin-top:20px}@media(max-width:850px){.control-grid{grid-template-columns:1fr}}'''
(PUBLIC/'style.css').write_text(STYLE,encoding='utf-8')
learn=[('Keep a session alive','Use an async user-message generator. Hold the second prompt on a promise until the first result and the student’s Continue action. Streaming an HTTP response alone is not SDK streaming input.'),('Switch models between turns','Call setModel on the existing Query object. Inspect the actual assistant model field for both turns and compare the returned session IDs.'),('Change permission mode deliberately','Start the classroom edit in plan mode. Review its proposal, then use the Continue button to call setPermissionMode("acceptEdits") before the scoped status.txt edit.'),('Apply runtime settings','Call applyFlagSettings with settings-file keys such as effortLevel, not the query option name effort. Observe actual hook metadata before and after the change.'),('Persist settings with clear scope','Call updateSettings for local outputStyle and the user default effort. These writes stay inside this app’s private project and SDK home. The saved user effort does not change the running session’s effort.'),('Verify later-session behavior','After writing settings, launch a separate verification query without an effort override. Compare its actual output style and hook effort with the running session’s evidence. Keep model-switch cache costs in mind.')]
body='''<div class="flow"><div><b>01 · Pause</b><p>First result, second prompt held</p></div><span>→</span><div><b>02 · Apply</b><p>Student Continue and SDK controls</p></div><span>→</span><div><b>03 · Verify</b><p>Actual turn and file evidence</p></div></div><section class="panel" id="controls"><h2>Steer one live classroom session</h2><p class="meta" id="configuration">Checking server configuration…</p><div class="control-grid"><div><label for="experiment">Experiment</label><select id="experiment"><option value="switch">Switch Sonnet → Opus between turns</option><option value="plan-act">Review a plan → approve one classroom edit</option><option value="runtime">Apply effortLevel at runtime</option><option value="persist">Persist local style and user effort privately</option></select></div><button class="primary" id="run" disabled>Start the two-turn session →</button></div><p class="note">Every experiment pauses after its first result. Review the actual evidence below, then click Apply changes and continue. The host awaits the SDK control acknowledgements before releasing prompt two.</p><p class="meta">The pinned models are defined in src/agent.ts. Model access depends on your account. No shell tool is enabled. Only the plan-to-act experiment can edit its own private status.txt, after the Continue action.</p></section>
<section class="step" id="approval-panel"><h2>Review, then continue</h2><p id="approval-state" aria-live="polite">No paused session yet.</p><button class="primary" id="continue" disabled>Apply changes and continue →</button><p class="meta">For plan-to-act, this button approves only the displayed classroom draft → reviewed change. Other experiments use it to apply their fixed configuration change. Automated tests and Playwright recordings drive this same button/API; they do not represent an external human approval. Stay on this page; the host has a six-minute timeout.</p></section>
<div class="workspace"><section class="panel" id="outcome"><div class="eyebrow">ACTUAL SDK RESULT</div><h2 id="status" aria-live="polite">Ready</h2><div class="stats"><div class="stat"><span>Latest query cost estimate</span><strong id="cost">—</strong></div></div><p class="meta">Latest session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p class="note" id="notice"></p></section><section class="panel" id="option-panel"><h2>Initial options</h2><p class="meta">Safe projection. Raw environment and absolute private paths are omitted. These initial values are distinct from the acknowledged changes and actual turn evidence below.</p><pre class="json-view"><code id="options" class="language-json">{ "state": "Waiting for a run" }</code></pre></section></div>
<section class="step" id="turn-panel"><h2>Observed configuration on each turn</h2><p id="session-proof">No session comparison yet.</p><div class="table"><table><thead><tr><th>Phase</th><th>Turn</th><th>Actual assistant model</th><th>Observed mode</th><th>Hook effort</th><th>Result</th><th>Session</th></tr></thead><tbody id="turns"></tbody></table></div><p class="meta">Model values come from assistant messages. Permission and effort values come from actual init/hook metadata; absent effort is labelled Not reported. A method acknowledgement and an observed effect are different evidence.</p></section>
<section class="step" id="control-panel"><h2>Real control requests and acknowledgements</h2><ul id="controls-observed"></ul><p class="meta">Acknowledged means the awaited SDK method completed. A rejected control never releases prompt two. The host then checks model messages, hooks, file contents or a new query for the relevant effect.</p></section>
<section class="step" id="file-panel"><h2>Classroom edit · actual file evidence</h2><p id="file-changed">No after-run evidence yet</p><div class="workspace"><div><h3>Before</h3><pre class="file-view" id="status-before">draft</pre></div><div><h3>After</h3><pre class="file-view" id="status-after">Waiting</pre></div></div><p class="meta">Only the plan-to-act experiment enables Edit, confined to this private status.txt. The host’s path/phase guard remains active even after acceptEdits. Other scenarios leave the file unchanged. These are application guards, not an OS sandbox.</p></section>
<section class="step" id="settings-panel"><h2>Persisted private settings · safe projection</h2><pre class="json-view"><code id="settings" class="language-json">{ "state": "No settings-write evidence yet" }</code></pre><p class="meta">The SDK writer updates the private project’s .claude/settings.local.json and the app-owned CLAUDE_CONFIG_DIR/settings.json. The projection shows only outputStyle and effort values. It never dumps authentication or the normal user’s Claude settings. Each new experiment resets only its owned fixture and experimental settings files.</p></section>
<section class="step" id="followup-panel"><h2>New-session verification</h2><p id="followup">Only the persisted-settings experiment starts this additional query.</p><p class="meta">The live session keeps its explicit low effort after updateSettings(userSettings). The separate verification query omits the effort option and loads the private user/local sources. Its own init and hook evidence should show Explanatory output style and medium effort. This is a new session, distinct from the two live turns above.</p></section>
<section class="step" id="lifecycle-panel"><h2>Pause, acknowledgement, release and close</h2><ul id="lifecycle"></ul></section><section class="step" id="event-panel"><h2>Actual SDK messages and tool requests</h2><ul id="events"></ul></section><section class="step" id="init-panel"><h2>Latest actual system/init</h2><pre><code id="init" class="language-json">{ "state": "Waiting for init" }</code></pre></section><section class="note"><h3>Lesson scope</h3><p>The four scenarios execute setModel, setPermissionMode, applyFlagSettings and both supported updateSettings targets. setModel() with no argument, Python controls, other settings keys and cache-cost calculations remain reference material. No cwd setter exists: use a new query to change project. A model switch can require processing the conversation at the new model’s rates; this lab does not isolate or benchmark cache misses. Cost fields are estimates and cumulative within a live query, so do not add its turn totals.</p></section><button id="download">Download actual observations</button>'''
document('/','Pause the session. <em>Change what comes next.</em>','Apply live SDK controls between two prompts, then verify the actual effects.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you will <em>learn.</em>','Separate a requested control, its acknowledgement, and the runtime evidence that follows.',cards(learn)+actions(('/run.html','Configure and run →'),('/architecture.html','Architecture →')))
setup='cd .\\agent-sdk\\lesson12-mid-session\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n# http://127.0.0.1:3112'
env='ANTHROPIC_API_KEY=your_api_key\nPORT=3112'
runsteps=[('Check prerequisites','Use Node.js 24+, npm and an Anthropic key with access to pinned Sonnet 4.6 and Opus 4.6 for the model-switch experiment. Keep optional dependencies enabled. Python is not needed to run this TypeScript app.',''),('Install, configure and start','From presentations run the commands below. Preserve an existing .env; otherwise copy the safe template. Enter your key locally and keep the terminal running. Shell variables take precedence over the optional file. The classroom model IDs are explicit constants in src/agent.ts.',snippet(setup,'powershell')+snippet(env,'dotenv')),('Switch the model between two turns','Start the default model-switch experiment. Wait for Paused after turn 1. Review the first answer and actual Sonnet model. Click Apply changes and continue. Inspect acknowledged setModel/setPermissionMode calls, actual Opus on turn 2 and the same live session ID.',''),('Review a plan, then approve one edit','Select the plan-to-act experiment and Start. Review the draft → reviewed proposal and plan-mode hook evidence. The file has not been approved for editing yet. Click Apply changes and continue. Verify acceptEdits, the actual guarded Edit and status.txt changing on disk.',''),('Apply a runtime effort setting','Choose runtime effort, Start, wait for the first result, then Continue. Inspect applyFlagSettings({ effortLevel: "medium" }) being acknowledged. Compare actual hook effort: low on turn 1, medium on turn 2. Do not infer hidden reasoning or guaranteed latency from the setting.',''),('Persist private settings and verify later behavior','Choose persisted settings, Start, wait and Continue. The real SDK writer saves local Explanatory style and user medium effort inside private classroom paths. Inspect file projections, live turn 2 still using low effort, and the separate new query loading Explanatory/medium without an effort option override.',''),('Read results and lifecycle in the correct scope','The two live results share a session ID. The persisted-settings verification query has its own ID. Read latest cumulative cost for each query; do not sum turn totals. Stay on the lab page while paused. Navigating away closes the response and aborts the run; restart if it times out.',''),('Use the CLI and troubleshoot','CLI samples automatically continue after the first result and label that automation. The web application waits for its button. Run samples sequentially. If Windows requests Git Bash, set its verified path. A second server start recognizes this app; use a different PORT for an unrelated listener. Ctrl+C stops it. Rejected methods or provider failures remain failures; no saved result substitutes for them.',snippet('npm run sample:env -- switch\nnpm run sample:env -- plan-act\nnpm run sample:env -- runtime\nnpm run sample:env -- persist\nnpm test','powershell'))]
body=''.join(f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{escape(t)}</h2><p>{escape(d)}</p>{c}</section>' for i,(t,d,c) in enumerate(runsteps,1))
document('/run.html','Configure and <em>run the live-control lab.</em>','Start, inspect the first result, apply the fixed change, then verify turn two.',body+actions(('/learn.html','← Learning goals'),('/','Open the lab →')))
specs=[
 ('Validate a fixed classroom experiment','src/server.ts','const config = validateConfig(input);','const config = validateConfig(input);','The host accepts one of four fixed experiments. The browser cannot supply arbitrary model strings, paths, settings objects or executable callbacks.',0,1),
 ('Prepare a private project and settings home','src/agent.ts','await writeFile(resolve(sdkHome(config), "settings.json"),','await writeFile(\n  resolve(sdkHome(config), "settings.json"), "{}\\n"\n);','Each scenario owns its classroom files and private SDK home. Fresh runs reset only those experimental settings files, never normal user configuration.',1,4),
 ('Build a typed asynchronous prompt stream','src/agent.ts','await secondReady;','async function* prompts(): AsyncGenerator<SDKUserMessage> {\n  yield userMessage(PROMPTS.first);\n  await secondReady;\n  // The actual second prompt depends on the experiment.\n  yield userMessage(PROMPTS.second);\n}','The generator yields a first user message and holds the next. The displayed normal read-task branch omits the plan-to-act prompt choice and cancellation check.',1,2),
 ('Start one live Query object','src/agent.ts','const session = query({ prompt: prompts(), options });','const session = query({ prompt: prompts(), options });','Keep the Query object returned by query. The SDK owns model/tool orchestration, while the host applies controls between completed prompts.',1,2),
 ('Observe actual turn-one configuration','src/agent.ts','permissionMode: input.permission_mode || null, effort: input.effort?.level || null','emit({ type: "hook",\n  phase: tracker.phase, turn: tracker.turn,\n  event: "PreToolUse",\n  permissionMode: input.permission_mode || null,\n  effort: input.effort?.level || null\n});','Hook metadata supplies observed permission and effort values; assistant messages separately supply actual model IDs. Missing metadata remains missing.',2,1),
 ('Wait for the student’s Continue action','src/agent.ts','activeGate = { runId, release };','activeGate = { runId, release };\n// The host awaits this gate after the first result.','The first result pauses the host. Only a matching active run ID can release its gate through the Continue endpoint. The web button is an actual classroom approval action; tests automate it explicitly.',0,1),
 ('Switch the model and permission mode','src/agent.ts','await control("setModel", SECOND_MODEL, () => session.setModel(SECOND_MODEL));','await control("setModel", SECOND_MODEL,\n  () => session.setModel(SECOND_MODEL));\nawait control("setPermissionMode", "acceptEdits",\n  () => session.setPermissionMode("acceptEdits"));','For the model-switch experiment, await both real methods before prompt two. The plan-to-act branch uses only the permission-mode setter, and its file guard remains active.',1,2),
 ('Apply settings-file keys at runtime','src/agent.ts','await control("applyFlagSettings", "effortLevel: medium", () => session.applyFlagSettings({ effortLevel: "medium" }));','await session.applyFlagSettings({\n  effortLevel: "medium"\n});','Use effortLevel, the settings-file key, instead of the query option effort. The acknowledged method changes this session; hooks on the next task verify the active effort.',1,2),
 ('Persist local and user settings deliberately','src/agent.ts','await control("updateSettings(localSettings)", "outputStyle: Explanatory", () => session.updateSettings("localSettings", { outputStyle: "Explanatory" }));','await session.updateSettings("localSettings", {\n  outputStyle: "Explanatory"\n});\nawait session.updateSettings("userSettings", {\n  effortLevel: "medium"\n});','The real SDK writer persists supported keys to private classroom files. Local output style applies on the next request; the user effort default does not change the current live session.',2,4),
 ('Release prompt two after acknowledgements','src/agent.ts','await applyChanges(session, config, emit);','await applyChanges(session, config, emit);\ntracker.turn = 2;\ntracker.acting = config.experiment === "plan-act";\n// Emit the released lifecycle event, then:\nreleaseSecond();','The host awaits every selected method before releasing the second user message. A rejected change prevents that release and remains a failure.',1,2),
 ('Verify the actual file after the live query','src/agent.ts','const after = await readFile(resolve(project(config), "status.txt"), "utf8");','const after = await readFile(\n  resolve(project(config), "status.txt"), "utf8"\n);','Read the real status file after closing the live query. A model claim or Edit request is not proof that the classroom change happened.',1,3),
 ('Load persisted settings in a fresh query','src/agent.ts','delete verificationOptions.effort;','delete verificationOptions.effort;\n// Keep the private user/local setting sources.\nconst verification = query({\n  prompt: PROMPTS.first, options: verificationOptions\n});','The verification query omits an effort override and uses the same private settings files. Its new session has actual style/effort evidence distinct from the two live turns.',1,2),
 ('Render results and compare observed turns','src/client.ts','if (e.type === "answer") renderMarkdown($("answer"), e.text);','if (e.type === "answer")\n  renderMarkdown($("answer"), e.text);','Render actual model text with the bundled Markdown parser and sanitizer. Keep acknowledgements, model IDs, hooks, files and new-session evidence separate.',1,0),
]
lanes=['Student UI','Node host','Live Query','Guarded files','Private settings'];steps=[];arrows=[]
words=['one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen']
extra={3:['async function* prompts(): AsyncGenerator<SDKUserMessage> {','if (!controller.signal.aborted) yield userMessage('],7:['await control("setPermissionMode", "acceptEdits", () => session.setPermissionMode("acceptEdits"));'],9:['await control("updateSettings(userSettings)", "effortLevel: medium", () => session.updateSettings("userSettings", { effortLevel: "medium" }));'],10:['releaseSecond();'],12:['const verification = query({ prompt: PROMPTS.first, options: verificationOptions });']}
for n,(title,source,anchor,code,explanation,a,b) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');assert anchor in text,(n,anchor)
 anchors=[anchor]+extra.get(n,[]);lines=[text[:text.index(v)].count('\n')+1 for v in anchors]
 steps.append(dict(number=n,title=title,source=source,code=code,language='typescript',explanation=explanation,firstLine=min(lines),lastLine=max(lines),anchors=anchors,sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {words[n-1]}. {explanation} The source label identifies the corresponding application statements.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><title>Lesson 12 live configuration, student gate and settings sequence</title><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" rx="22" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" font-weight="bold" fill="#101a44">Pause → approve → await controls → release → verify actual effects</text>']
